const euro=n=>n==null||!Number.isFinite(n)?'—':Math.round(n).toLocaleString('es-ES')+' €';
function percentile(a,p){a=[...a].sort((x,y)=>x-y);const i=(a.length-1)*p,l=Math.floor(i),h=Math.ceil(i);return l===h?a[l]:a[l]+(a[h]-a[l])*(i-l)}
function riskRank(level){return {'Bajo':1,'Medio':2,'Alto':3,'Muy alto':4}[level]||4}
function riskClass(level){return level==='Bajo'?'good':level==='Medio'?'warn':'bad'}

